int path_to_char(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i = 0;
    int j = 0;

    if (tolen <= 0 || fromlen <= 0) {
        return -EINVAL;
    }

    while (i < fromlen && j < tolen - 1) {
        unsigned char type = from[i++];

        switch (type) {
            case 0: /* symlink */
                if (j + 8 > tolen) {
                    return -ENAMETOOLONG;
                }
                memcpy(to + j, "symlink", 8);
                j += 8;
                break;
            case 1: /* directory indicator */
                if (j + 1 > tolen) {
                    return -ENAMETOOLONG;
                }
                to[j++] = '/';
                break;
            case 2: /* file name */
                while (i < fromlen && j < tolen - 1) {
                    to[j++] = from[i++];
                    if (from[i - 1] == '\0') {
                        break;
                    }
                }
                if (i >= fromlen && fromlen > 0 && from[fromlen - 1] != '\0') {
                    if (j < tolen - 1) {
                        to[j++] = '\0';
                    } else {
                        return -ENAMETOOLONG;
                    }
                }
                break;
            default:
                return -EINVAL;
        }
    }

    if (j < tolen) {
        to[j] = '\0';
    } else {
        return -ENAMETOOLONG;
    }

    return 0;
}

int path_to_char(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i, j = 0;
    unsigned char *component_start = from;
    int component_len;

    for (i = 0; i < fromlen; i++) {
        if (from[i] == '/') {
            if (from[i + 1] != '\0' && from[i + 1] != '/') {
                component_len = i - (component_start - from);
                if (j + component_len + 1 >= tolen) {
                    return -ENAMETOOLONG;
                }

                memcpy(to + j, component_start, component_len);
                j += component_len;
                to[j++] = '/'; // Add the directory separator
                component_start = from + i + 1;
            }
            // Skip consecutive slashes
            while (i + 1 < fromlen && from[i + 1] == '/')
                i++;
        }
    }

    // Handle the last component
    component_len = fromlen - (component_start - from);
    if (j + component_len >= tolen) {
        return -ENAMETOOLONG;
    }

    memcpy(to + j, component_start, component_len);
    j += component_len;
    to[j] = '\0'; // Null-terminate the string

    return 0;
}

int path_to_string(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i, j;
    unsigned char *src = from;
    unsigned char *dest = to;
    int remaining = tolen;

    for (i = 0; i < fromlen; i++) {
        unsigned char type = src[i] & 0xF0;
        unsigned char len = (src[i] & 0x0F) + 1;
        unsigned char *component = &src[i + 1];

        switch (type) {
            case 0x00: // Symlink
                if (remaining < len + 2) {
                    return -ENAMETOOLONG;
                }
                *dest++ = '[';
                for (j = 0; j < len; j++) {
                    *dest++ = component[j];
                }
                *dest++ = ']';
                remaining -= len + 2;
                break;
            case 0x10: // Directory
                if (remaining < len + 1) {
                    return -ENAMETOOLONG;
                }
                for (j = 0; j < len; j++) {
                    *dest++ = component[j];
                }
                *dest++ = '/';
                remaining -= len + 1;
                break;
            case 0x20: // File
                if (remaining < len) {
                    return -ENAMETOOLONG;
                }
                for (j = 0; j < len; j++) {
                    *dest++ = component[j];
                }
                remaining -= len;
                break;
            default:
                return -EINVAL;
        }
    }

    if (remaining > 0) {
        *dest = '\0';
    } else {
        return -ENAMETOOLONG;
    }

    return 0;
}

int path_to_char(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i = 0, j = 0;

    if (tolen <= 0)
        return -EINVAL;

    while (i < fromlen && j < tolen - 1) {
        if (from[i] == '/') {
            to[j++] = '/';
            i++;
        } else if (from[i] == '.') {
            if (i + 1 < fromlen && from[i + 1] == '.' && (i + 2 >= fromlen || from[i + 2] == '/')) {
                /* Handle directory indicator */
                if (j > 1 && to[j - 1] == '/') {
                    j--;
                    while (j > 0 && to[j - 1] != '/') {
                        j--;
                    }
                } else {
                    to[j++] = '.';
                    to[j++] = '.';
                }
                i += 3;
            } else {
                to[j++] = '.';
                i++;
            }
        } else {
            /* Assume it's part of a filename or symlink */
            to[j++] = from[i++];
        }
    }

    if (j >= tolen)
        return -ENAMETOOLONG;

    to[j] = '\0';
    return 0;
}

int path_to_char(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i = 0;
    int j = 0;

    if (tolen < 1)
        return -EINVAL;

    while (i < fromlen) {
        if (j >= tolen - 1)
            return -ENAMETOOLONG;

        if (from[i] == 0) {
            to[j++] = '.';
            i++;
        } else if (from[i] == 1) {
            if (j + 6 >= tolen - 1)
                return -ENAMETOOLONG;
            memcpy(&to[j], "symlink", 6);
            j += 6;
            i++;
        } else if (from[i] == 2) {
            if (j + 10 >= tolen - 1)
                return -ENAMETOOLONG;
            memcpy(&to[j], "directory", 10);
            j += 10;
            i++;
        } else {
            if (j + from[i] >= tolen - 1)
                return -ENAMETOOLONG;
            memcpy(&to[j], &from[i], from[i]);
            j += from[i];
            i += from[i];
        }
    }

    to[j] = '\0';
    return 0;
}
